const d06 = (c: number[], t: number) => (m06 ? Math.sin(Math.PI * t) ** 2 * (c[0] + c[1] * Math.cos(Math.PI * t) + c[2] * Math.cos(2 * Math.PI * t)) : 0);
// r29 `&m06deep=1` (needs match06): see m06deepShift. The original anchors (WORLD0) define the original route, so the formula
// below is unchanged whether or not the shift was applied by an earlier Course in this page.
const old06 = (t: number) =>
  V(
    s6.x - 4 * Math.sin(Math.PI * t) + (WORLD0.chamber.center.x - s6.x) * smooth(0.4, 1, t) + d06(path06.dx, t),
    s6.y + 12.5 * Math.pow(Math.sin(Math.PI * Math.min(t / 0.82, 1)), 1.15) - 4.5 * smooth(0.5, 1, t) + d06(path06.dy, t),
    s6.z - 46 * t,
  );
const deep06 = m06 && flag05('m06deep');
if (deep06) {
  // the first metres stay EXACTLY the original route (Benny's approved checkpoint pose and the r25 hole patch s 197.2-203.3 depend
  // on them): raw points up to axial aKeep along the painted tunnel axis, then the designed centre line (route06deep.json,
  // tools/match06/r29_design_route.py), whose last point is the moved 07 entrance
  const O6 = V(route06deep.O[0], route06deep.O[1], route06deep.O[2]), ax6 = V(route06deep.ax[0], route06deep.ax[1], route06deep.ax[2]);
  for (let i = 1; i <= 34; i++) { const p = old06(i / 34); if (p.clone().sub(O6).dot(ax6) > route06deep.aKeep) break; push(p); }
  for (const q of route06deep.points) push(V(q[0], q[1], q[2]));
  applyWorldShift(pts[pts.length - 1].clone().sub(old06(1)));
} else {
  applyWorldShift(new THREE.Vector3());
  seg(34, old06);
}
mark('07');

