import * as THREE from 'three';
import { PROJ05_INVERSE } from '../vfx/waterRibbon';

interface Layout {
  camera: { matrixWorld: number[]; fov: number; size: [number, number] };
  floorY: number;
  chamber: { cx: number; cy: number; r: number; zBack: number; zDoor: number };
  arch: { z: number; outer: { cx: number; cy: number; r: number }; inner: { cx: number; cy: number; r: number }; depth: number };
  pipe: { cx: number; cy: number; r: number; z0: number; z1: number };
  backwall: { z: number; holeR: number };
  platform: { cx: number; cz: number; r: number; topY: number; rimBottomY: number; floorY: number; tiltDeg: number };
  towel: { cx: number; cz: number; w: number; h: number; y0: number; d: number };
  spouts: Record<string, { c: [number, number, number]; rx: number; ry: number }>;
}

export interface Match08 {
  group: THREE.Group;
  /** the approved picture's splash ring around Benny (camera-facing card; Game places it at Benny + splashOffset) */
  splash: THREE.Mesh;
  splashOffset: THREE.Vector3;
  /** render the projector depth map once (needs the renderer); call after the group is in the scene */
  bakeDepth(renderer: THREE.WebGLRenderer): void;
  /** live post values for the inverse (exposure from the renderer, render size for the vignette inverse) */
  sync(renderer: THREE.WebGLRenderer, w: number, h: number): void;
}

const VERT = /* glsl */ `
uniform mat4 uProjVP;
varying vec4 vProj;
      5 149:L.arch
      4 152:L.arch
      4 145:L.pipe
      2 159:L.arch
      2 156:L.pipe
      2 144:L.pipe
      2 143:L.pipe
      1 182:L.spouts
      1 179:L.towel
      1 169:L.platform
      1 166:L.pipe
      1 166:L.floorY
      1 165:L.pipe
      1 157:L.backwall
      1 156:L.backwall
      1 151:L.arch
      1 148:L.arch
      1 140:L.chamber
      1 106:L.camera
      1 105:L.camera
  // (assets/textures/match08/coins08.json, from the locked 08 camera), instead of the 08 + 09 rows above
  if (m08) {
    const s0 = st('08').s0, s1 = st('11').s0;
    const cam = coins08.faceTo as [number, number, number];
    const toRiver = (x: number, z: number) => {
      let best = s0, bd = Infinity;
      for (let s = s0; s <= s1; s += 0.05) { const p = course.sample(s).pos; const d = (p.x - x) ** 2 + (p.z - z) ** 2; if (d < bd) { bd = d; best = s; } }
      const f = course.sample(best);
      return { s: best, lat: (x - f.pos.x) * f.right.x + (z - f.pos.z) * f.right.z, y: f.pos.y };
    };
    for (const c of coins08.coins) {
      let r = toRiver(c.x, c.z), h = c.h, scale = c.scale;
      // keep every picture coin collectible: if it lies beyond pickup reach (|lateral| > 1.1), slide it along its own view
      // ray from the approved camera (same pixel in the approved view) to the nearest depth within reach, above the water;
      // its size scales with the depth so it still covers the painted coin
      if (Math.abs(r.lat) > 1.1) {
        const P = [c.x, r.y + c.h, c.z], D = [P[0] - cam[0], P[1] - cam[1], P[2] - cam[2]];
        let pick: { k: number; r: typeof r; h: number } | null = null;
        for (let k = 0.2; k <= 1.8; k += 0.01) {
          const q = [cam[0] + D[0] * k, cam[1] + D[1] * k, cam[2] + D[2] * k], rq = toRiver(q[0], q[2]), hq = q[1] - rq.y;
          if (Math.abs(rq.lat) <= 1.0 && hq >= 0.3 && (!pick || Math.abs(k - 1) < Math.abs(pick.k - 1))) pick = { k, r: rq, h: hq };
        }
        if (pick) { r = pick.r; h = pick.h; scale = c.scale * pick.k; }
      }
      add(course.stageAtS(r.s).id, r.s, r.lat, h, { scale, faceTo: cam });
